import java.io.*;import com.jpexs.decompiler.flash.*;import com.jpexs.decompiler.flash.abc.avm2.instructions.*;
public class UnlockTest{
 public static void main(String[] ar)throws Exception{SWF s=new SWF(new FileInputStream(ar[0]),false);for(var t:s.getAbcList()){var a=t.getABC();var b=a.findBodyByClassAndName("SD","loadGame");if(b==null)continue;var c=b.getCode();for(int i=c.code.size()-1;i>=0;i--){if(!c.code.get(i).definition.instructionName.equals("returnvoid"))continue;int p=i;c.insertInstruction(p++,new AVM2Instruction(0,0x60,new int[]{a.constants.getPublicQnameId("SD",true)}),b);for(int j=0;j<7;j++){for(int k=0;k<20;k++)c.insertInstruction(p++,new AVM2Instruction(0,0x24,new int[]{k}),b);c.insertInstruction(p++,new AVM2Instruction(0,0x56,new int[]{20}),b);}c.insertInstruction(p++,new AVM2Instruction(0,0x56,new int[]{7}),b);c.insertInstruction(p++,new AVM2Instruction(0,0x61,new int[]{a.constants.getPublicQnameId("gunsOwned",true)}),b);}b.setCode(c);b.max_stack=Math.max(b.max_stack,30);((com.jpexs.decompiler.flash.tags.Tag)t).setModified(true);}s.saveTo(new FileOutputStream(ar[1]));}
}
